// Auto-generated from Natural Earth 110m land polygons (public domain).
// A 512x256 equirectangular bit mask: bit set = land. Used by GlobeHero to
// place continent dots. Regenerate with scripts described in GlobeHero.tsx.
const MASK_W = 512;
const MASK_H = 256;

const MASK_B64: string = [
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////w==',
].join('');

let bits: Uint8Array | null = null;

function decode(): Uint8Array {
  if (bits) return bits;
  const bin = atob(MASK_B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  bits = out;
  return out;
}

/** True when the given latitude/longitude (degrees) falls on land. */
export function isLand(latDeg: number, lonDeg: number): boolean {
  const b = decode();
  const x = Math.min(MASK_W - 1, Math.max(0, Math.floor(((lonDeg + 180) / 360) * MASK_W)));
  const y = Math.min(MASK_H - 1, Math.max(0, Math.floor(((90 - latDeg) / 180) * MASK_H)));
  const idx = y * MASK_W + x;
  return (b[idx >> 3] & (1 << (idx & 7))) !== 0;
}
